   "sintesis": "Donita Rodriguez, jefa de Análisis Macroeconómico de APOYO Consultoría, fue designada como nueva miembro del Consejo Fiscal. “ Esta designación reconoce su sólida trayectoria en análisis macroeconómico y fiscal, experiencia que ahora aportará al Consejo Fiscal para contribuir a la evaluación técnica e independiente de la política fiscal del país ”, destacó APOYO Consultoría.",
